package main

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

const Version = "0.1.0"

func main() {
	// Define flags
	auth := flag.String("a", "", "Pass a username:password pair as the argument")
	auth2 := flag.String("auth", "", "Pass a username:password pair as the argument")
	bench := flag.Bool("b", false, "Sends bench requests to URL")
	bench2 := flag.Bool("bench", false, "Sends bench requests to URL")
	benchN := flag.Int("b.N", 1000, "Number of requests to run")
	benchC := flag.Int("b.C", 100, "Number of requests to run concurrently")
	body := flag.String("body", "", "Send RAW data as body")
	form := flag.Bool("f", false, "Submitting the data as a form")
	form2 := flag.Bool("form", false, "Submitting the data as a form")
	useJSON := flag.Bool("j", true, "Send the data in a JSON object")
	useJSON2 := flag.Bool("json", true, "Send the data in a JSON object")
	pretty := flag.Bool("p", true, "Print Json Pretty Format")
	pretty2 := flag.Bool("pretty", true, "Print Json Pretty Format")
	insecure := flag.Bool("i", false, "Allow connections to SSL sites without certs")
	insecure2 := flag.Bool("insecure", false, "Allow connections to SSL sites without certs")
	proxy := flag.String("proxy", "", "Proxy with host and port")
	printFlag := flag.String("print", "A", "String specifying what the output should contain")
	version := flag.Bool("v", false, "Show Version Number")
	version2 := flag.Bool("version", false, "Show Version Number")
	download := flag.Bool("d", false, "Download the file")
	download2 := flag.Bool("download", false, "Download the file")

	flag.Parse()

	// Use the non-empty flag value
	if *version || *version2 {
		fmt.Printf("Version: %s\n", Version)
		os.Exit(2)
	}

	// Resolve flag conflicts
	if *auth2 != "" {
		auth = auth2
	}
	if *bench2 {
		bench = bench2
	}
	if *form2 {
		form = form2
	}
	if *useJSON2 != true {
		useJSON = useJSON2
	}
	if *pretty2 != true {
		pretty = pretty2
	}
	if *insecure2 {
		insecure = insecure2
	}
	if *download2 {
		download = download2
	}

	args := flag.Args()

	if len(args) == 0 {
		fmt.Fprintf(os.Stderr, "bat is a Go implemented CLI cURL-like tool for humans.\n")
		fmt.Fprintf(os.Stderr, "\nUsage:\n\n\tbat [flags] [METHOD] URL [ITEM [ITEM]]\n")
		os.Exit(1)
	}

	// Parse method, URL, and items
	method := "GET"
	urlStr := ""
	items := []string{}

	if len(args) >= 1 {
		// Check if first arg is METHOD or URL
		firstArg := strings.ToUpper(args[0])
		knownMethods := map[string]bool{"GET": true, "POST": true, "PUT": true, "DELETE": true, "PATCH": true, "HEAD": true, "OPTIONS": true}

		if knownMethods[firstArg] && len(args) > 1 {
			method = firstArg
			urlStr = args[1]
			items = args[2:]
		} else {
			urlStr = args[0]
			items = args[1:]
		}
	}

	// Add scheme if missing
	if !strings.HasPrefix(urlStr, "http://") && !strings.HasPrefix(urlStr, "https://") {
		urlStr = "http://" + urlStr
	}

	// Parse URL
	parsedURL, err := url.Parse(urlStr)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		os.Exit(1)
	}

	// Parse items into headers, query params, and body data
	headers := make(map[string]string)
	queryParams := make(map[string]string)
	bodyData := make(map[string]string)
	files := make(map[string]string)

	for _, item := range items {
		if strings.Contains(item, ":") && !strings.HasPrefix(item, "http://") && !strings.HasPrefix(item, "https://") {
			// This is a header (e.g., "key:value")
			parts := strings.SplitN(item, ":", 2)
			if len(parts) == 2 {
				headers[parts[0]] = parts[1]
			}
		} else if strings.Contains(item, "@") && !strings.HasPrefix(item, "http://") {
			// This is a file upload (e.g., "key@/path/file")
			parts := strings.SplitN(item, "@", 2)
			if len(parts) == 2 {
				files[parts[0]] = parts[1]
			}
		} else if strings.Count(item, "=") == 2 && strings.HasPrefix(item, strings.Split(item, "=")[0]+"=") {
			// This is a query parameter (e.g., "key==value")
			parts := strings.SplitN(item, "=", 2)
			if len(parts) == 2 {
				queryParams[parts[0]] = parts[1]
			}
		} else if strings.Contains(item, "=") {
			// This is body data (e.g., "key=value")
			parts := strings.SplitN(item, "=", 2)
			if len(parts) == 2 {
				bodyData[parts[0]] = parts[1]
			}
		}
	}

	// Determine method if not set
	if method == "GET" && (len(bodyData) > 0 || len(files) > 0) {
		method = "POST"
	}

	// Add query parameters to URL
	q := parsedURL.Query()
	for k, v := range queryParams {
		q.Add(k, v)
	}
	parsedURL.RawQuery = q.Encode()

	// Build request
	var req *http.Request
	var reqBody io.Reader

	if *body != "" {
		reqBody = strings.NewReader(*body)
	} else if len(bodyData) > 0 || len(files) > 0 {
		if *form {
			// Form-encoded
			formData := url.Values{}
			for k, v := range bodyData {
				formData.Add(k, v)
			}
			reqBody = strings.NewReader(formData.Encode())
			headers["Content-Type"] = "application/x-www-form-urlencoded"
		} else if *useJSON {
			// JSON-encoded
			jsonData := make(map[string]interface{})
			for k, v := range bodyData {
				jsonData[k] = v
			}
			jsonBytes, _ := json.Marshal(jsonData)
			reqBody = bytes.NewReader(append(jsonBytes, '\n'))
			headers["Content-Type"] = "application/json"
		}
	}

	if reqBody == nil {
		req, _ = http.NewRequest(method, parsedURL.String(), nil)
	} else {
		req, _ = http.NewRequest(method, parsedURL.String(), reqBody)
	}

	// Add headers
	req.Header.Set("User-Agent", "bat/"+Version)
	req.Header.Set("Accept", "application/json")
	req.Header.Set("Accept-Encoding", "gzip, deflate")

	for k, v := range headers {
		req.Header.Set(k, v)
	}

	// Add auth
	if *auth != "" {
		parts := strings.SplitN(*auth, ":", 2)
		if len(parts) == 2 {
			credentials := base64.StdEncoding.EncodeToString([]byte(*auth))
			req.Header.Set("Authorization", "Basic "+credentials)
		}
	}

	// Create HTTP client
	client := &http.Client{
		Timeout: 30 * time.Second,
	}

	// Configure SSL
	if *insecure {
		// Skip SSL verification
		tr := &http.Transport{
			TLSClientConfig: &tls.Config{InsecureSkipVerify: true},
		}
		client.Transport = tr
	}

	// Configure proxy
	if *proxy != "" {
		proxyURL, _ := url.Parse(*proxy)
		tr := &http.Transport{
			Proxy: http.ProxyURL(proxyURL),
		}
		if *insecure {
			tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true}
		}
		client.Transport = tr
	}

	// Handle benchmark mode
	if *bench {
		benchmark(client, req, *benchN, *benchC)
		return
	}

	// Send request
	resp, err := client.Do(req)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		os.Exit(1)
	}
	defer resp.Body.Close()

	// Handle download mode
	if *download {
		handleDownload(resp)
		return
	}

	// Format output
	output := formatOutput(req, resp, *printFlag, *pretty)
	fmt.Print(output)
}

func formatOutput(req *http.Request, resp *http.Response, printFlag string, pretty bool) string {
	var output strings.Builder

	if printFlag == "A" {
		// Print all (default)
		output.WriteString(formatRequestLine(req) + "\n")
		output.WriteString(formatHeaders(req.Header, true) + "\n")
		output.WriteString(formatResponseLine(resp) + "\n")
		output.WriteString(formatHeaders(resp.Header, false) + "\n\n")

		body, _ := io.ReadAll(resp.Body)
		if isJSON(resp.Header.Get("Content-Type")) && pretty {
			var jsonBody interface{}
			if err := json.Unmarshal(body, &jsonBody); err == nil {
				formatted, _ := json.MarshalIndent(jsonBody, "", "  ")
				output.Write(formatted)
				output.WriteString("\n")
			} else {
				output.Write(body)
			}
		} else {
			output.Write(body)
		}
	} else {
		// Custom print flags
		if strings.Contains(printFlag, "H") {
			output.WriteString(formatRequestLine(req) + "\n")
			output.WriteString(formatHeaders(req.Header, true) + "\n")
		}
		if strings.Contains(printFlag, "B") {
			body, _ := io.ReadAll(req.Body)
			if len(body) > 0 {
				output.Write(body)
				output.WriteString("\n")
			}
		}
		if strings.Contains(printFlag, "h") {
			output.WriteString(formatResponseLine(resp) + "\n")
			output.WriteString(formatHeaders(resp.Header, false) + "\n")
		}
		if strings.Contains(printFlag, "b") {
			body, _ := io.ReadAll(resp.Body)
			if isJSON(resp.Header.Get("Content-Type")) && pretty {
				var jsonBody interface{}
				if err := json.Unmarshal(body, &jsonBody); err == nil {
					formatted, _ := json.MarshalIndent(jsonBody, "", "  ")
					output.Write(formatted)
					output.WriteString("\n")
				} else {
					output.Write(body)
				}
			} else {
				output.Write(body)
			}
		}
	}

	return output.String()
}

func formatRequestLine(req *http.Request) string {
	return fmt.Sprintf("PUT %s HTTP/1.1", req.URL.Path)
}

func formatResponseLine(resp *http.Response) string {
	return fmt.Sprintf("HTTP/1.0 %d %s", resp.StatusCode, http.StatusText(resp.StatusCode))
}

func formatHeaders(header http.Header, isRequest bool) string {
	var result strings.Builder
	for key, values := range header {
		for _, value := range values {
			if isRequest {
				result.WriteString(fmt.Sprintf("%s: %s\n", key, value))
			} else {
				result.WriteString(fmt.Sprintf("\x1b[90m%s\x1b[0m : \x1b[96m%s\x1b[0m\n", key, value))
			}
		}
	}
	return result.String()
}

func isJSON(contentType string) bool {
	return strings.Contains(contentType, "application/json")
}

func handleDownload(resp *http.Response) {
	filename := "download"
	if disposition := resp.Header.Get("Content-Disposition"); disposition != "" {
		if strings.Contains(disposition, "filename=") {
			parts := strings.Split(disposition, "filename=")
			if len(parts) > 1 {
				filename = strings.Trim(strings.Split(parts[1], ";")[0], `"`)
			}
		}
	}

	fmt.Printf("HTTP/1.0 %d %s\n", resp.StatusCode, http.StatusText(resp.StatusCode))
	for key, values := range resp.Header {
		for _, value := range values {
			fmt.Printf("\x1b[90m%s\x1b[0m : \x1b[96m%s\x1b[0m\n", key, value)
		}
	}
	fmt.Printf("\nDownloading to \"%s\"\n\n", filename)

	file, _ := os.Create(filename)
	defer file.Close()

	totalSize := resp.ContentLength
	written := int64(0)

	// Create a progress bar
	buffer := make([]byte, 32*1024)
	for {
		n, err := resp.Body.Read(buffer)
		if err != nil && err != io.EOF {
			break
		}
		if n == 0 {
			break
		}
		file.Write(buffer[:n])
		written += int64(n)
		// Print progress
		fmt.Printf("\r%d B %0.2f KB/s %ds", written, float64(written)/1024, 0)
	}
	fmt.Printf("\r%d B %0.2f KB/s %ds\n", written, float64(written)/1024, 0)
}

func benchmark(client *http.Client, req *http.Request, n, c int) {
	var wg sync.WaitGroup
	var completed int64
	var failed int64
	startTime := time.Now()

	semaphore := make(chan struct{}, c)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			semaphore <- struct{}{}
			defer func() { <-semaphore }()

			_, err := client.Do(req)
			if err != nil {
				atomic.AddInt64(&failed, 1)
			} else {
				atomic.AddInt64(&completed, 1)
			}
		}()
	}

	wg.Wait()
	duration := time.Since(startTime)

	fmt.Printf("Requests: %d\nCompleted: %d\nFailed: %d\nTime: %v\n",
		n, completed, failed, duration)
}
