		if strings.Contains(*printFlag, "H") {
			fmt.Printf("%s %s %s\n", req.Method, req.URL.Path, "HTTP/1.1")
			for k, v := range req.Header {
				for _, val := range v {
					fmt.Printf("%s: %s\n", k, val)
				}
			}
			fmt.Println()
		}
